        answer: 'ໃນປະຕິທິນ ຫຼື ບັນທຶກປະຈຳວັນ ໃຫ້ບັນທຶກວັນທີ່ປະຈຳເດືອນເລີ່ມ ໄລຍະເວລາທີ່ມາ ແລະ ປະລິມານເລືອດປະຈຳເດືອນ. ຂໍ້ມູນນີ້ສ້າງເປັນປະຫວັດສ່ວນຕົວຂອງທ່ານ ແລະ ໃຊ້ໃນການຄາດຄະເນທີ່ສະແດງໃນ AWA.',
