        answer: 'AWA ຄາດຄະເນປະຈຳເດືອນຄັ້ງຕໍ່ໄປ ໄລຍະມີໂອກາດຕັ້ງຄັນສູງ ແລະ ການຕົກໄຂ່ຂອງທ່ານ ຈາກປະຫວັດສ່ວນຕົວ ຄວາມຍາວຂອງຮອບເດືອນ ແລະ ຂໍ້ມູນທີ່ທ່ານບັນທຶກ. ການຄາດຄະເນບໍ່ເຄີຍອີງໃສ່ຮອບເດືອນມາດຕະຖານ 28 ວັນເທົ່ານັ້ນ.',
