        answer: 'ໄດ້. ມີຮູບສ່ວນຕົວທີ່ປອດໄພ ຕົວຢ່າງເຊັ່ນເພື່ອຕິດຕາມການປ່ຽນແປງຂອງສິວ ການຂຶ້ນຂອງຂົນ ຫຼື ອາການທາງຜິວໜັງ.',
