  // Phase 7C — App Lock, PIN setup/confirm/management, biometrics/Face ID,
  // PrivateAccess, SecuritySetup. Deliberately separate from the
  // `privateSectionAuth`/`privateIntimacy*` namespaces above, which belong to
  // the "Vie intime" private-section system (a different PIN, a different
  // Keychain service, a different copy voice) — see each service's own
