          howItWorksParagraph1: 'AWA ຮ່ວມກັນຊ່ວຍໃຫ້ທ່ານເບິ່ງສະເພາະຂໍ້ມູນທີ່ຄູ່ຂອງທ່ານເລືອກແບ່ງປັນກັບທ່ານເທົ່ານັ້ນ.',
          howItWorksParagraph2: 'ຕົວຢ່າງ, ທ່ານອາດເຫັນຂໍ້ມູນບາງຢ່າງກ່ຽວກັບຮອບເດືອນ, ປະຈຳເດືອນຄັ້ງຕໍ່ໄປ ຫຼື ໄລຍະມີໂອກາດຕັ້ງຄັນສູງຂອງເຂົາ ເມື່ອເປີດການແບ່ງປັນສຳລັບຂໍ້ມູນເຫຼົ່ານັ້ນ.',
          howItWorksParagraph3: 'ຂໍ້ມູນທີ່ເຫັນໄດ້ຂຶ້ນກັບການເລືອກຂອງເຂົາສະເໝີ. ເຂົາສາມາດປ່ຽນສິ່ງທີ່ແບ່ງປັນໄດ້ທຸກເວລາ.',
