          hiddenInfoParagraph1: 'ຄູ່ຂອງທ່ານຍັງຄວບຄຸມຂໍ້ມູນທີ່ເຂົາຢາກແບ່ງປັນກັບທ່ານ.',
          hiddenInfoParagraph2: 'ຖ້າຂໍ້ມູນບໍ່ປາກົດໃນພື້ນທີ່ຂອງທ່ານ ມັນອາດໝາຍຄວາມວ່າເຂົາຍັງບໍ່ໄດ້ເລືອກແບ່ງປັນ.',
